draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < W; i += 50) {
    ctx.moveTo(i, H / 2 + Math.sin(t + i * 0.01) * 20);
    ctx.lineTo(i + 50, H / 2 + Math.sin(t + (i + 50) * 0.01) * 20);
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 10, H / 2 + Math.cos(t) * 10, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
